      janma: "\u092E\u093E\u0930\u094D\u0917\u0936\u0940\u0930\u094D\u0937 \u0936\u0941\u0915\u094D\u0932 \u092A\u094D\u0930\u0925\u092E",
      tap: "\u092E\u093E\u0930\u094D\u0917\u0936\u0940\u0930\u094D\u0937 \u0936\u0941\u0915\u094D\u0932 \u092A\u094D\u0930\u0925\u092E",
      gyan: "\u0915\u093E\u0930\u094D\u0924\u093F\u0915 \u0936\u0941\u0915\u094D\u0932 \u0926\u094D\u0935\u093F\u0924\u0940\u092F\u093E",
      moksha: "\u0915\u093E\u0930\u094D\u0924\u093F\u0915 \u0936\u0941\u0915\u094D\u0932 \u0905\u0937\u094D\u091F\u092E\u0940"
